/**
 * Simulation data (branch `simulacion`): 300 receipts in the 6 batches of one period, the Tayrona and SAP contracts
 * behind them and, for every file, the result the design says it must reach. Generated by a loop with a fixed seed,
 * so every run uses the same data.
 *
 * Run: node sim/generate.ts [outDir=sim/out] [period=YYYY-MM]
 */
import { mkdirSync, rmSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

export const BLOCKS = [
  { block: 'CASH', day: '7', source: 'TAYRONA' },
  { block: 'AVVILLAS', day: '12', source: 'TAYRONA' },
  { block: 'BANCOLOMBIA', day: '18', source: 'TAYRONA' },
  { block: 'DAVIVIENDA', day: '23', source: 'TAYRONA' },
  { block: 'ANGLO', day: '26', source: 'SAP' },
  { block: 'OTHERS', day: 'último', source: 'TAYRONA' },
] as const;

export const NEW_CONCEPT = 'SANCIÓN';

/** What each file must end as, according to the design (docs/context and docs/architecture/decisiones.md). */
export interface Expected {
  readonly upload: 'REGISTERED' | 'DUPLICATE' | 'DUPLICATE_CONFLICT';
  readonly state?: string;
  readonly errorType?: string;
  readonly deliveryState?: string;
  /** Extra checks: the address ends suppressed, or a history event must exist. */
  readonly suppressed?: boolean;
  readonly historyEvent?: string;
  /** Where the expectation comes from. */
  readonly why: string;
}

export interface SimFile {
  readonly block: string;
  readonly fileName: string;
  readonly scenario: string;
  readonly contract: string;
  readonly email?: string;
  readonly content: 'pdf' | 'not-pdf' | 'duplicate';
  readonly seed: string;
  /** Duplicates only: the normal file whose content it repeats. */
  readonly duplicateOf?: string;
  readonly expected: Expected;
  /** `extra`: not part of the batch's 50 files; used by a scenario of the audit (D32-D53) at another moment of the month. */
  readonly phase?: 'extra';
}

type Scenario = { readonly name: string; readonly expected: Expected; readonly contract?: (c: Contract) => void };
interface Contract {
  activo: boolean;
  nombre_conjunto: string;
  correo: string | null;
}

const delivered = (why: string, deliveryState = 'ACCEPTED'): Expected => ({ upload: 'REGISTERED', state: 'SENT', deliveryState, why });

/** Delivery scenarios of the ZeptoMail simulator, put in the recipient address (`+zm-<scenario>`). */
const DELIVERY: readonly Scenario[] = [
  { name: 'softbounce', expected: delivered('§10: soft bounce, ZeptoMail may still retry; not final at closure', 'SOFT_BOUNCE') },
  { name: 'softhard', expected: { ...delivered('§10.3: soft then hard bounce → suppressed', 'HARD_BOUNCE'), suppressed: true } },
  { name: 'softdelivered', expected: delivered('§7.3: soft bounce then delivered') },
  { name: 'hardbounce', expected: { ...delivered('§10.3: hard bounce → local suppression + alert', 'HARD_BOUNCE'), suppressed: true } },
  { name: 'complaint', expected: { ...delivered('P5: complaint → suppressed', 'COMPLAINT'), suppressed: true } },
  { name: 'processfailed', expected: { ...delivered('§9.4: process failed after acceptance; no SENT → FAILED transition', 'UNCONFIRMED'), historyEvent: 'PROVIDER_PROCESS_FAILED' } },
  { name: 'nowebhook', expected: delivered('D21: webhook lost, delivery found in the logs') },
  { name: 'nolog', expected: { ...delivered('Simulation: never visible in the logs → 120 s wait runs out', 'UNCONFIRMED'), historyEvent: 'DELIVERY_WAIT_TIMEOUT' } },
];

/** Send-time scenarios: rejected by the provider, lost response (timeout) and 503/429 (never accepted). */
const REJECTED: Scenario = { name: 'SM_113', expected: { upload: 'REGISTERED', state: 'FAILED', errorType: 'PROVIDER_REJECTED', why: '§12.4: SM_113 → FAILED / PROVIDER_REJECTED' } };
const TIMEOUT: Scenario = { name: 'timeout', expected: delivered('§9.2: lost response → UNCERTAIN; accepted, so reconciliation finds it → SENT') };
const UNAVAILABLE = (code: '503' | '429'): Scenario => ({
  name: code,
  expected: { upload: 'REGISTERED', state: 'FAILED', errorType: 'NOT_FOUND_AT_PROVIDER', why: `§9.2/§9.4: HTTP ${code} → UNCERTAIN; not in the logs at the last lookup → FAILED` },
});

/** Upload-time scenarios. */
const NOT_FOUND: Scenario = { name: 'contract-not-found', expected: { upload: 'REGISTERED', state: 'PENDING', errorType: 'CONTRACT_NOT_FOUND', why: '§6: contract unknown to the source → needs correction, not sent' } };
const INACTIVE: Scenario = {
  name: 'contract-inactive',
  expected: { upload: 'REGISTERED', state: 'PENDING', errorType: 'CONTRACT_INACTIVE', why: '§6: inactive contract → needs correction, not sent' },
  contract: (c) => (c.activo = false),
};
const NO_EMAIL: Scenario = {
  name: 'contract-without-email',
  expected: { upload: 'REGISTERED', state: 'PENDING', errorType: 'CONTRACT_WITHOUT_EMAIL', why: '§6: no email → needs correction, not sent' },
  contract: (c) => (c.correo = null),
};
const SOURCE_DOWN: Scenario = { name: 'source-unavailable', expected: { upload: 'REGISTERED', state: 'PENDING', errorType: 'SOURCE_UNAVAILABLE', why: '§6: source answers 503 → needs refresh, not sent' } };
const INVALID_NAME: Scenario = { name: 'invalid-name', expected: { upload: 'REGISTERED', state: 'INVALID', errorType: 'INVALID_NAME', why: '§4.2: double space after CNCPT' } };
const UNKNOWN_CONCEPT: Scenario = { name: 'unknown-concept', expected: { upload: 'REGISTERED', state: 'INVALID', errorType: 'UNKNOWN_CONCEPT', why: '§4.2: concept not in the catalog (case-sensitive)' } };
const NOT_PDF: Scenario = { name: 'not-a-pdf', expected: { upload: 'REGISTERED', state: 'INVALID', errorType: 'NOT_A_PDF', why: '§5: content is not a PDF' } };
const DUPLICATE: Scenario = { name: 'duplicate', expected: { upload: 'DUPLICATE_CONFLICT', why: 'D31: same content as another file of the batch under another name → both blocked until the operator chooses a name (the runner chooses the original one)' } };
const OK: Scenario = { name: 'ok', expected: delivered('Normal send, delivered') };

const CONCEPTS = ['PAGO ADMINISTRACIÓN', 'CUOTA EXTRA', 'MULTA'] as const;
const STREETS = ['Altos', 'Palmas', 'Robles', 'Cedros', 'Pinos', 'Almendros', 'Guaduales', 'Arrayanes', 'Laureles', 'Ceibas'] as const;

/** mulberry32: small deterministic PRNG. */
function random(seed: number): () => number {
  let a = seed;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function currentPeriod(now = new Date(), timeZone = 'America/Bogota'): string {
  const parts = new Intl.DateTimeFormat('en-CA', { timeZone, year: 'numeric', month: '2-digit' }).formatToParts(now);
  return `${parts.find((p) => p.type === 'year')?.value}-${parts.find((p) => p.type === 'month')?.value}`;
}

export function generate(): { files: SimFile[]; contracts: Record<'TAYRONA' | 'SAP', Record<string, Contract>> } {
  const rnd = random(2026);
  const pick = <T>(items: readonly T[]): T => items[Math.floor(rnd() * items.length)] as T;
  const contracts: Record<'TAYRONA' | 'SAP', Record<string, Contract>> = { TAYRONA: {}, SAP: {} };
  const files: SimFile[] = [];
  let tayrona = 100_000;
  let sap = 700_000;

  for (const [index, { block, source }] of BLOCKS.entries()) {
    // 50 per batch: 33 normal, 8 delivery scenarios, 2 send-time, 7 upload-time (one normal replaced by a source outage in AVVILLAS).
    const scenarios: Scenario[] = [
      ...Array.from({ length: 33 }, () => OK),
      ...DELIVERY,
      REJECTED,
      index % 2 === 0 ? TIMEOUT : UNAVAILABLE(index === 5 ? '429' : '503'),
      NOT_FOUND,
      INACTIVE,
      NO_EMAIL,
      INVALID_NAME,
      UNKNOWN_CONCEPT,
      NOT_PDF,
      DUPLICATE,
    ];
    if (block === 'AVVILLAS') scenarios[0] = SOURCE_DOWN;
    // Fisher-Yates with the seeded PRNG: scenarios spread through the batch.
    for (let i = scenarios.length - 1; i > 0; i -= 1) {
      const j = Math.floor(rnd() * (i + 1));
      [scenarios[i], scenarios[j]] = [scenarios[j] as Scenario, scenarios[i] as Scenario];
    }

    let newConceptUses = 0;
    for (const [n, scenario] of scenarios.entries()) {
      const number = source === 'SAP' ? (sap += 1) : (tayrona += 1);
      const contractId = scenario === NOT_FOUND ? `9${number}` : scenario === SOURCE_DOWN ? '9990503' : String(number);
      const complex = `Conjunto ${pick(STREETS)} ${number}`;
      const slug = `conjunto${number}`;
      const local = scenario === OK || scenario.name.startsWith('contract') || scenario === INVALID_NAME || scenario === UNKNOWN_CONCEPT || scenario === NOT_PDF || scenario === DUPLICATE ? slug : `${slug}+zm-${scenario.name}`;
      const contract: Contract = { activo: true, nombre_conjunto: complex, correo: `${local}@clientes.test` };
      scenario.contract?.(contract);
      if (scenario !== NOT_FOUND && scenario !== SOURCE_DOWN) contracts[source][contractId] = contract;

      // The new concept (added before BANCOLOMBIA, retired before ANGLO) is used by two normal files of batches 3 to 5.
      let concept: string = pick(CONCEPTS);
      let expected = scenario.expected;
      if (scenario === OK && index >= 2 && index <= 4 && newConceptUses < 2) {
        concept = NEW_CONCEPT;
        newConceptUses += 1;
        if (block === 'ANGLO') expected = { upload: 'REGISTERED', state: 'INVALID', errorType: 'UNKNOWN_CONCEPT', why: `D25: ${NEW_CONCEPT} retired before this batch → rejected in later uploads` };
      }
      const detail = `${complex} ${block.toLowerCase()} ${String(n + 1).padStart(2, '0')}`;
      const fileName =
        scenario === INVALID_NAME
          ? `${detail} CNCPT  ${concept} CNTRT ${contractId}.pdf`
          : scenario === UNKNOWN_CONCEPT
            ? `${detail} CNCPT ${concept.toLowerCase()} CNTRT ${contractId}.pdf`
            : `${detail} CNCPT ${concept} CNTRT ${contractId}.pdf`;
      const file: SimFile = {
        block,
        fileName,
        scenario: scenario.name,
        contract: contractId,
        ...(contract.correo ? { email: contract.correo } : {}),
        content: scenario === NOT_PDF ? 'not-pdf' : scenario === DUPLICATE ? 'duplicate' : 'pdf',
        // A duplicate gets its content after the loop, from a normal file of the batch (see below).
        seed: `${block}-${n}-${number}`,
        expected,
      };
      files.push(file);
    }
    // The duplicate copies a normal file (valid name, valid PDF, expected to be sent): the nearest one before it, else
    // the next one. Copying an invalid file would make the app keep the duplicate under its valid name (A1).
    const batch = files.filter((f) => f.block === block);
    const position = batch.findIndex((f) => f.scenario === DUPLICATE.name);
    const isNormal = (f: SimFile) => f.scenario === OK.name && f.expected.state === 'SENT';
    const original = [...batch.slice(0, position)].reverse().find(isNormal) ?? batch.slice(position + 1).find(isNormal);
    if (!original) throw new Error(`no normal file to duplicate in ${block}`);
    const at = files.indexOf(batch[position] as SimFile);
    files[at] = { ...(batch[position] as SimFile), seed: original.seed, duplicateOf: original.fileName };
  }
  // Extra files of the audit scenarios (sim/run.ts), outside the 300 of the month:
  // - CASH, after batch 1: a lost-response send aborted by the operator while the provider keeps it waiting (D32); the
  //   receipt is released UNCERTAIN, the reconciliation finds it in the logs → SENT, and the STOPPED batch with nothing
  //   left settles to COMPLETED and purges its files (D41).
  // - AVVILLAS, before batch 2: the 51st file of one upload, refused with 413 before anything is registered (D48).
  const extra = (block: string, source: 'TAYRONA' | 'SAP', scenario: string, local: string, expected: Expected): void => {
    const number = source === 'SAP' ? (sap += 1) : (tayrona += 1);
    const contractId = String(number);
    const complex = `Conjunto ${pick(STREETS)} ${number}`;
    contracts[source][contractId] = { activo: true, nombre_conjunto: complex, correo: `conjunto${number}${local}@clientes.test` };
    files.push({
      block,
      fileName: `${complex} ${block.toLowerCase()} extra CNCPT ${pick(CONCEPTS)} CNTRT ${contractId}.pdf`,
      scenario,
      contract: contractId,
      email: `conjunto${number}${local}@clientes.test`,
      content: 'pdf',
      seed: `${block}-extra-${number}`,
      expected,
      phase: 'extra',
    });
  };
  extra('CASH', 'TAYRONA', 'abort-settle', '+zm-timeout', delivered('D32/D41: aborted while waiting for the provider → UNCERTAIN → found in the logs → SENT; the stopped batch settles to COMPLETED'));
  extra('AVVILLAS', 'TAYRONA', 'upload-budget', '', { upload: 'REGISTERED', why: 'D48: the 51st file of one request → 413 UPLOAD_TOO_LARGE, nothing registered (never uploaded on its own)' });
  return { files, contracts };
}

export function pdf(seed: string): Buffer {
  return Buffer.from(`%PDF-1.7\n1 0 obj << /Type /Catalog /Seed (${seed}) >> endobj\ntrailer << /Root 1 0 R >>\n%%EOF\n`, 'latin1');
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const out = process.argv[2] ?? 'sim/out';
  const { files, contracts } = generate();
  rmSync(join(out, 'pdfs'), { recursive: true, force: true });
  for (const { block } of BLOCKS) mkdirSync(join(out, 'pdfs', block), { recursive: true });
  for (const file of files) {
    // Every duplicate must repeat exactly one normal file of its batch.
    if (file.content === 'duplicate') {
      const originals = files.filter((f) => f !== file && f.block === file.block && f.seed === file.seed);
      if (originals.length !== 1 || originals[0]?.scenario !== 'ok' || originals[0]?.expected.state !== 'SENT') throw new Error(`bad duplicate: ${file.fileName}`);
    }
    writeFileSync(join(out, 'pdfs', file.block, file.fileName), file.content === 'not-pdf' ? Buffer.from(`Hoja de cálculo ${file.seed}\n`) : pdf(file.seed));
  }
  mkdirSync(join(out, 'data'), { recursive: true });
  writeFileSync(join(out, 'data', 'tayrona.json'), JSON.stringify(contracts.TAYRONA, null, 2));
  writeFileSync(join(out, 'data', 'sap.json'), JSON.stringify(contracts.SAP, null, 2));
  writeFileSync(join(out, 'data', 'expected.json'), JSON.stringify(files, null, 2));
  const count = (block: string) => files.filter((f) => f.block === block).length;
  process.stdout.write(`${files.length} files (${BLOCKS.map((b) => `${b.block} ${count(b.block)}`).join(', ')}); ${Object.keys(contracts.TAYRONA).length} Tayrona and ${Object.keys(contracts.SAP).length} SAP contracts → ${out}\n`);
}
